    serializer.buffer.putUint8List(self);
  }

  @protected
  void sse_encode_list_record_string_string(
    List<(String, String)> self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.length, serializer);
    for (final item in self) {
      sse_encode_record_string_string(item, serializer);
    }
  }

  @protected
  void sse_encode_opt_String(String? self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs

    sse_encode_bool(self != null, serializer);
    if (self != null) {
      sse_encode_String(self, serializer);
    }
  }

  @protected
  void sse_encode_opt_box_autoadd_pattern_change(
    PatternChange? self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs

    sse_encode_bool(self != null, serializer);
    if (self != null) {
      sse_encode_box_autoadd_pattern_change(self, serializer);
    }
  }

  @protected
  void sse_encode_opt_box_autoadd_photo_status(
    PhotoStatus? self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs

    sse_encode_bool(self != null, serializer);
    if (self != null) {
      sse_encode_box_autoadd_photo_status(self, serializer);
    }
  }

  @protected
  void sse_encode_opt_box_autoadd_u_32(int? self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs

    sse_encode_bool(self != null, serializer);
    if (self != null) {
      sse_encode_box_autoadd_u_32(self, serializer);
    }
  }

  @protected
  void sse_encode_opt_box_autoadd_u_64(BigInt? self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs

    sse_encode_bool(self != null, serializer);
    if (self != null) {
      sse_encode_box_autoadd_u_64(self, serializer);
    }
  }

  @protected
  void sse_encode_opt_list_prim_f_64_strict(
    Float64List? self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs

    sse_encode_bool(self != null, serializer);
    if (self != null) {
      sse_encode_list_prim_f_64_strict(self, serializer);
    }
  }

  @protected
  void sse_encode_pattern_change(PatternChange self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.kind, serializer);
    sse_encode_f_64(self.mm, serializer);
  }

  @protected
  void sse_encode_photo_request(PhotoRequest self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.quality, serializer);
    sse_encode_String(self.lighting, serializer);
    sse_encode_u_32(self.width, serializer);
    sse_encode_u_32(self.height, serializer);
    sse_encode_opt_box_autoadd_u_32(self.samples, serializer);
    sse_encode_opt_box_autoadd_u_32(self.bounces, serializer);
    sse_encode_bool(self.denoise, serializer);
  }

  @protected
  void sse_encode_photo_status(PhotoStatus self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_u_32(self.samples, serializer);
    sse_encode_u_32(self.total, serializer);
    sse_encode_u_32(self.width, serializer);
    sse_encode_u_32(self.height, serializer);
    sse_encode_bool(self.finished, serializer);
    sse_encode_f_64(self.seconds, serializer);
    sse_encode_opt_String(self.error, serializer);
  }

  @protected
  void sse_encode_picked_point(PickedPoint self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.id, serializer);
    sse_encode_f_64(self.xMm, serializer);
    sse_encode_f_64(self.yMm, serializer);
  }

  @protected
  void sse_encode_record_string_string(
    (String, String) self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.$1, serializer);
    sse_encode_String(self.$2, serializer);
  }

  @protected
  void sse_encode_sim_status(SimStatus self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_bool(self.loaded, serializer);
    sse_encode_bool(self.running, serializer);
    sse_encode_f_64(self.timeS, serializer);
    sse_encode_f_64(self.stepMs, serializer);
    sse_encode_u_32(self.particles, serializer);
    sse_encode_f_64(self.maxSeamGapMm, serializer);
  }

  @protected
  void sse_encode_u_32(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint32(self);
  }

  @protected
  void sse_encode_u_64(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }

  @protected
  void sse_encode_u_8(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint8(self);
  }

  @protected
  void sse_encode_unit(void self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
  }

  @protected
  void sse_encode_usize(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }

  @protected
  void sse_encode_view_kind(ViewKind self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.index, serializer);
  }
}

@sealed
class EngineImpl extends RustOpaque implements Engine {
  // Not to be used by end users
  EngineImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  EngineImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_Engine,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_Engine,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_EnginePtr,
  );

  /// Add a notch on the edge within `max_mm` of pattern point (`x_mm`,
  /// `y_mm`), where that point is along it (`notch.add`). Returns the
  /// notch, or `None` off the edges (and on linked mirror copies, which
  /// follow their source).
  String? addNotchNear({
    required double xMm,
    required double yMm,
    required double maxMm,
  }) => RustLib.instance.api.crateApiEngineEngineAddNotchNear(
    that: this,
    xMm: xMm,
    yMm: yMm,
    maxMm: maxMm,
  );

  /// Insert a point on the edge within `max_mm` of pattern point
  /// (`x_mm`, `y_mm`), where that point is along it (`edge.split`; the
  /// curve keeps its shape). Returns the new point, or `None` off the
  /// edges or within `max_mm` of an edge's ends.
  String? addPointNear({
    required double xMm,
    required double yMm,
    required double maxMm,
  }) => RustLib.instance.api.crateApiEngineEngineAddPointNear(
    that: this,
    xMm: xMm,
    yMm: yMm,
    maxMm: maxMm,
  );

  /// How many changes agents have made that the UI can show: it
  /// refreshes when this moves. Asked several times a second, so it never
  /// waits: while an agent holds the project (a long action such as
  /// `simulate`), its latest changes are counted once it lets go.
  BigInt agentChanges() =>
      RustLib.instance.api.crateApiEngineEngineAgentChanges(that: this);

  AgentStatus agentStatus() =>
      RustLib.instance.api.crateApiEngineEngineAgentStatus(that: this);

  /// Let AI agents reach this project (`r3d mcp --attach`), writing the
  /// endpoint into `library_dir`; or stop, disconnecting any agent.
  void allowAgents({required String libraryDir, required bool allow}) =>
      RustLib.instance.api.crateApiEngineEngineAllowAgents(
        that: this,
        libraryDir: libraryDir,
        allow: allow,
      );

  /// Attach a view rendering into a UI texture (`surface`: platform handle
  /// from the UI side, an `IOSurfaceRef` pointer on macOS), or without
  /// one into a texture of its own, read back with `read_view`. Returns
  /// the view id.
  int attachView({
    required ViewKind kind,
    BigInt? surface,
    required int width,
    required int height,
  }) => RustLib.instance.api.crateApiEngineEngineAttachView(
    that: this,
    kind: kind,
    surface: surface,
    width: width,
    height: height,
  );

  /// A click at pixel (`x`, `y`) of a view. Updates the shared selection
  /// and returns it (panel ids).
  List<String> click({
    required int view,
    required double x,
    required double y,
    required bool extend,
  }) => RustLib.instance.api.crateApiEngineEngineClick(
    that: this,
    view: view,
    x: x,
    y: y,
    extend: extend,
  );

  /// Put the photo away: the 3D view shows the live garment again.
  void closePhoto() =>
      RustLib.instance.api.crateApiEngineEngineClosePhoto(that: this);

  /// Stop rendering into a view (its UI texture is about to go away).
  void detachView({required int view}) => RustLib.instance.api
      .crateApiEngineEngineDetachView(that: this, view: view);

  /// Close the connected agent's session; agents stay allowed.
  void disconnectAgent() =>
      RustLib.instance.api.crateApiEngineEngineDisconnectAgent(that: this);

  /// A drag of (`dx`, `dy`) pixels: orbit the 3D camera, pan the board.
  void drag({required int view, required double dx, required double dy}) =>
      RustLib.instance.api.crateApiEngineEngineDrag(
        that: this,
        view: view,
        dx: dx,
        dy: dy,
      );

  /// Write an export to `path`, a file the user chose (anywhere): the
  /// pattern, or the garment as the 3D view shows it now (the running
  /// drape, or its starting positions), with the avatar if `avatar`.
  void exportFile({
    required ExportFormat format,
    required String path,
    required bool avatar,
  }) => RustLib.instance.api.crateApiEngineEngineExportFile(
    that: this,
    format: format,
    path: path,
    avatar: avatar,
  );

  /// Fit the board to the pattern again.
  void fitBoard({required int view}) =>
      RustLib.instance.api.crateApiEngineEngineFitBoard(that: this, view: view);

  /// Import the pieces of a pattern from a file the user chose
  /// (anywhere; DXF, SVG or PDF): the file is copied into the project's
  /// `imports/` folder, then read, as one undo step. `units` (`mm`, `cm`,
  /// `in`, `px`…) overrides what the file says. Returns the JSON result
  /// of `import.pattern`: `panels`, `ignored`, and `scale` (`assumed`
  /// when the file did not say how big a unit is).
  String importPattern({required String path, String? units}) => RustLib
      .instance
      .api
      .crateApiEngineEngineImportPattern(that: this, path: path, units: units);

  /// Look at the body from one side, framed head to toe.
  void lookFrom({required CameraSide side}) =>
      RustLib.instance.api.crateApiEngineEngineLookFrom(that: this, side: side);

  /// How the photo is coming along; `None` when the 3D view shows the
  /// live garment.
  PhotoStatus? photoStatus() =>
      RustLib.instance.api.crateApiEngineEnginePhotoStatus(that: this);

  /// Pick the edge within `max_mm` of pattern point (`x_mm`, `y_mm`), as
  /// a click on it would (its piece selected). Returns the edge.
  String? pickEdgeNear({
    required double xMm,
    required double yMm,
    required double maxMm,
  }) => RustLib.instance.api.crateApiEngineEnginePickEdgeNear(
    that: this,
    xMm: xMm,
    yMm: yMm,
    maxMm: maxMm,
  );

  /// ⌥-click at (`x`, `y`) in the 3D view: pin the cloth there, where it
  /// is now (a `pin.add` command, so it is saved and undoable; the running
  /// simulation follows). Returns the new pin's id, or `None` when there
  /// is no cloth under the cursor.
  String? pinAt({required int view, required double x, required double y}) =>
      RustLib.instance.api.crateApiEngineEnginePinAt(
        that: this,
        view: view,
        x: x,
        y: y,
      );

  /// Pointer down at (`x`, `y`): in the 3D view, on the cloth, get ready
  /// to drag it. With `Adjust` (⇧ held) the drag changes the pattern at
  /// the contour edge under the cursor: an open edge (a hem) is
  /// lengthened, a seam is taken in or let out (at the nearer end when
  /// grabbed near one). With `Move` (⌘ held) it moves the piece around
  /// the body (its placement). Otherwise the drag pulls the cloth. Returns
  /// whether there is something to drag (then moves should call `pull`);
  /// otherwise drags orbit as usual.
  bool press({
    required int view,
    required double x,
    required double y,
    required Gesture gesture,
  }) => RustLib.instance.api.crateApiEngineEnginePress(
    that: this,
    view: view,
    x: x,
    y: y,
    gesture: gesture,
  );

  /// Pointer moved to (`x`, `y`) after `press`: pull the cloth there (on
  /// the plane facing the camera through the grabbed point; the
  /// simulation runs while it is held); with the Length tool, move the
  /// edge by the vertical distance dragged (down = longer); with the Fit
  /// tool, take the seam in by twice the distance dragged towards the
  /// body (away lets it out). Returns the change so far (mm) for the
  /// pattern tools.
  PatternChange? pull({
    required int view,
    required double x,
    required double y,
  }) => RustLib.instance.api.crateApiEngineEnginePull(
    that: this,
    view: view,
    x: x,
    y: y,
  );

  /// The last frame of a view attached without a UI surface, as BGRA
  /// pixels, row after row (platforms without shared textures).
  Future<Uint8List> readView({required int view}) =>
      RustLib.instance.api.crateApiEngineEngineReadView(that: this, view: view);

  /// Pointer up: let go of the cloth.
  void release() =>
      RustLib.instance.api.crateApiEngineEngineRelease(that: this);

  /// Render a view and wait until the GPU is done, so the UI never shows
  /// a half-drawn frame. Returns the CPU + GPU time in milliseconds.
  double renderView({required int view}) => RustLib.instance.api
      .crateApiEngineEngineRenderView(that: this, view: view);

  /// Start the simulation again from the pattern: the pieces around the
  /// body, paused.
  SimStatus resetSimulation() =>
      RustLib.instance.api.crateApiEngineEngineResetSimulation(that: this);

  /// Run one step (a JSON object, as in scripts and MCP) and return its
  /// JSON result. Changes are saved immediately.
  String run({required String stepJson}) => RustLib.instance.api
      .crateApiEngineEngineRun(that: this, stepJson: stepJson);

  /// Run a script (a JSON array of steps, with `"$N.path"` references to
  /// earlier results) and return the JSON array of results. Used for
  /// templates. The project is saved once at the end.
  String runScript({required String scriptJson}) => RustLib.instance.api
      .crateApiEngineEngineRunScript(that: this, scriptJson: scriptJson);

  /// Run or pause the simulation. Running with nothing loaded loads the
  /// garment first.
  SimStatus runSimulation({required bool running}) => RustLib.instance.api
      .crateApiEngineEngineRunSimulation(that: this, running: running);

  /// Save the photo as it is now as a PNG file at `path` (anywhere the
  /// user chose).
  Future<void> savePhoto({required String path}) => RustLib.instance.api
      .crateApiEngineEngineSavePhoto(that: this, path: path);

  /// Replace the shared selection with these panel ids; unknown ids are
  /// ignored. Returns the resulting selection.
  List<String> select({required List<String> panels}) => RustLib.instance.api
      .crateApiEngineEngineSelect(that: this, panels: panels);

  /// The edge picked within the selection (by a click near a border, in
  /// either view), if any.
  String? selectedEdge() =>
      RustLib.instance.api.crateApiEngineEngineSelectedEdge(that: this);

  /// The corners picked on the board: one, or two to measure between.
  List<PickedPoint> selectedPoints() =>
      RustLib.instance.api.crateApiEngineEngineSelectedPoints(that: this);

  /// The shared selection (panel ids).
  List<String> selection() =>
      RustLib.instance.api.crateApiEngineEngineSelection(that: this);

  /// Set the canvas colours from the UI design system, so the board and
  /// the 3D view match the app theme.
  void setCanvas({required CanvasColors colors}) => RustLib.instance.api
      .crateApiEngineEngineSetCanvas(that: this, colors: colors);

  /// The latest simulation state.
  SimStatus simulationStatus() =>
      RustLib.instance.api.crateApiEngineEngineSimulationStatus(that: this);

  /// Start a photo of the garment as the 3D view shows it now (camera,
  /// drape), replacing any other; the 3D view shows it while it
  /// refines. A size of 0 takes the 3D view's size.
  PhotoStatus startPhoto({required PhotoRequest request}) => RustLib
      .instance
      .api
      .crateApiEngineEngineStartPhoto(that: this, request: request);

  /// Stop refining the photo; it keeps the samples taken so far.
  void stopPhoto() =>
      RustLib.instance.api.crateApiEngineEngineStopPhoto(that: this);

  /// Finish the line: it becomes an internal line on the pattern
  /// (`internal_line.add`; a style line, a pocket placement…), on the
  /// source piece when drawn on a linked mirror copy. Returns the new
  /// line's id, or `None` when the stroke was too short.
  String? strokeEnd() =>
      RustLib.instance.api.crateApiEngineEngineStrokeEnd(that: this);

  /// Start drawing on the garment at (`x`, `y`) of a 3D view. Returns
  /// whether the pointer is on the cloth.
  bool strokeStart({required int view, required double x, required double y}) =>
      RustLib.instance.api.crateApiEngineEngineStrokeStart(
        that: this,
        view: view,
        x: x,
        y: y,
      );

  /// Continue the line to (`x`, `y`): points on other pieces, or off the
  /// cloth, are skipped.
  void strokeTo({required int view, required double x, required double y}) =>
      RustLib.instance.api.crateApiEngineEngineStrokeTo(
        that: this,
        view: view,
        x: x,
        y: y,
      );

  /// The pattern point (mm) under pixel (`x`, `y`) of a board.
  Float64List? toPattern({
    required int view,
    required double x,
    required double y,
  }) => RustLib.instance.api.crateApiEngineEngineToPattern(
    that: this,
    view: view,
    x: x,
    y: y,
  );

  /// The pixel of a board showing pattern point (`x_mm`, `y_mm`).
  Float64List? toView({
    required int view,
    required double xMm,
    required double yMm,
  }) => RustLib.instance.api.crateApiEngineEngineToView(
    that: this,
    view: view,
    xMm: xMm,
    yMm: yMm,
  );

  /// Remove a pin (`pin.remove`); the cloth there moves again.
  void unpin({required String pin}) =>
      RustLib.instance.api.crateApiEngineEngineUnpin(that: this, pin: pin);

  /// A scroll of `amount` (positive = zoom in) at pixel (`x`, `y`).
  void zoom({
    required int view,
    required double x,
    required double y,
    required double amount,
  }) => RustLib.instance.api.crateApiEngineEngineZoom(
    that: this,
    view: view,
    x: x,
    y: y,
    amount: amount,
  );
}
